import pty,sys,os
def run(cmd, env=None):
    e = dict(os.environ); 
    if env: e.update(env)
    out=[]
    def rd(fd):
        d=os.read(fd,1024); out.append(d); return d
    pid,fd = pty.fork()
    if pid==0:
        os.execvpe("/bin/sh",["/bin/sh","-c",cmd],e)
    try:
        while True:
            d=os.read(fd,1024)
            if not d: break
            out.append(d)
    except OSError: pass
    os.waitpid(pid,0)
    return b"".join(out)
print(repr(run(sys.argv[1], {"TERM":sys.argv[2]} if len(sys.argv)>2 else None)))

