    reps = {
        '<CR>': '\r', '<LF>': '\n', '<EOF>': '\x04', '<ETX>': '\x03',
        '<TAB>': '\t', '<ESC>': '\x1b', '<BS>': '\x7f', '<BS8>': '\x08',
        '<UP>': '\x1b[A', '<DOWN>': '\x1b[B', '<RIGHT>': '\x1b[C', '<LEFT>': '\x1b[D',
        '<HOME>': '\x1b[H', '<END>': '\x1b[F', '<DEL>': '\x1b[3~',
        '<PGUP>': '\x1b[5~', '<PGDN>': '\x1b[6~',
        '<BEL>': '\x07', '<NUL>': '\x00', '<SUB>': '\x1a', '<FS>': '\x1c',
    }
    for i in range(1, 27):
        reps['<C-%s>' % chr(ord('a') + i - 1)] = chr(i)
    for k, v in reps.items():
        s = s.replace(k, v)
    return s
